using System;using System.Drawing;using System.Reflection;
class LoadingEmblemChecks{[STAThread]static void Main(){int last=-1;for(int n=0;n<30;n++)using(var screen=new MenuLoadingScreen()){screen.Start();int selected=(int)typeof(MenuLoadingScreen).GetField("emblem",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(screen);if(selected<0||selected>4||selected==last)throw new Exception("selection invalid");last=selected;}using(var preview=new Bitmap(1000,650))using(var g=Graphics.FromImage(preview)){MenuLoadingScreen.DrawFrame(g,preview.Size,.5,.5,"战斗",null,null,2);if(preview.GetPixel(0,0).ToArgb()!=Color.Black.ToArgb())throw new Exception("background must be black");preview.Save("D:/WORK/Cet6Story/.validation/loading-random-preview.png");}Console.WriteLine("PASS five emblems, fixed per-load random selection, no immediate repeats and black background");}}
